#include <iostream>
#include <list>

int main() {
    int n = 0;
    if (!(std::cin >> n)) return 1;
    if (n < 1 || n > 1000) return 1;
    std::list<int> values;
    for (int i = 0; i < n; i++) {
        int value = 0;
        if (!(std::cin >> value)) return 1;
        if (value < -10000 || value > 10000) return 1;
        values.push_back(value);
    }
    values.sort();
    for (int value : values) {
        std::cout << value << "\n";
    }
    return 0;
}
